import*as i18n from"../../../../core/i18n/i18n.js";import*as TraceEngine from"../../../../models/trace/trace.js";export class TimelineOverviewCalculator{#i=TraceEngine.Types.Timing.MilliSeconds(0);#n=TraceEngine.Types.Timing.MilliSeconds(100);workingArea;navStartTimes;computePosition(i){return(i-this.#i)/this.boundarySpan()*this.workingArea}positionToTime(i){return i/this.workingArea*this.boundarySpan()+this.#i}setBounds(i,n){this.#i=i,this.#n=n}setNavStartTimes(i){this.navStartTimes=i}setDisplayWidth(i){this.workingArea=i}reset(){this.setBounds(TraceEngine.Types.Timing.MilliSeconds(0),TraceEngine.Types.Timing.MilliSeconds(100))}formatValue(i,n){if(this.navStartTimes)for(let n=this.navStartTimes.length-1;n>=0;n--){const e=TraceEngine.Helpers.Timing.microSecondsToMilliseconds(this.navStartTimes[n].ts);if(i>e){i-=e-this.zeroTime();break}}return i18n.TimeUtilities.preciseMillisToString(i-this.zeroTime(),n)}maximumBoundary(){return this.#n}minimumBoundary(){return this.#i}zeroTime(){return this.#i}boundarySpan(){return TraceEngine.Types.Timing.MilliSeconds(this.#n-this.#i)}}